\section{Introduction}

\subsection{The problem}
Let $G$ be a finite abelian group, written additively, and let $A,B\subseteq G$. The sumset is
$A+B=\{a+b: a\in A,\ b\in B\}$, and the basic question of additive combinatorics is how small
$|A+B|$ can be relative to $|A|,|B|$. The trivial answer is the \emph{pigeonhole bound}
\begin{equation}\label{eq:pigeon}
|A+B|\;\ge\;\max(|A|,|B|),
\end{equation}
obtained by injecting $B$ into $A+B$ via $y\mapsto a_0+y$ for a fixed $a_0\in A$, and
symmetrically.

One standard route to improvements is Fourier-analytic. Write $\widehat G$ for the character
group of $G$, and for $f:G\to\CC$ put $\widehat f(\psi)=\sum_{x\in G}f(x)\overline{\psi(x)}$.
The \emph{representation function}
\begin{equation}\label{eq:rep}
r_{A,B}(c)=\#\{(a,b)\in A\times B: a+b=c\}=(1_A*1_B)(c)
\end{equation}
has transform $\widehat{1_A}\widehat{1_B}$; its principal coefficient is $|A||B|$, and all
remaining spectral mass is the \emph{nonprincipal Fourier energy}
\begin{equation}\label{eq:E}
E(A,B)=\sum_{\psi\in\widehat G,\ \psi\neq 0}\bigl|\widehat{1_A}(\psi)\bigr|^2
\bigl|\widehat{1_B}(\psi)\bigr|^2 .
\end{equation}
A Cauchy--Schwarz argument comparing $r_{A,B}$ with its mean value $|A||B|/|G|$ gives the
\emph{covering bound}
\begin{equation}\label{eq:star}
\bigl|\{c: r_{A,B}(c)>0\}\bigr|\;\ge\;\frac{|G|\,(|A||B|)^2}{(|A||B|)^2+E(A,B)} .
\tag{$\star$}
\end{equation}
Since the support of $r_{A,B}$ is exactly $A+B$ (Proposition~\ref{prop:supp}),
\eqref{eq:star} is a lower bound for $|A+B|$ in purely spectral terms. What is not obvious is
what it is \emph{worth}: for which sets does it improve on \eqref{eq:pigeon}, by how much, and
how does one evaluate $E$, a sum over $|G|$ characters?

\subsection{Results}
Define the \emph{additive energy}
\begin{equation}\label{eq:Etil}
\Etil(A,B)=\sum_{c\in G} r_{A,B}(c)^2
=\#\{(a,b,a',b')\in A\times B\times A\times B: a+b=a'+b'\} .
\end{equation}

\begin{theoremA}[Energy identity]
For all $A,B\subseteq G$, \quad $E(A,B)=|G|\,\Etil(A,B)-(|A||B|)^2 .$
\end{theoremA}

\begin{theoremB}[Collapse of the covering bound]
For nonempty $A,B\subseteq G$ the right-hand side of \eqref{eq:star} equals
\[
\frac{|G|(|A||B|)^2}{(|A||B|)^2+E(A,B)}=\frac{(|A||B|)^2}{\Etil(A,B)}
=\frac{\bigl(\sum_c r_{A,B}(c)\bigr)^2}{\sum_c r_{A,B}(c)^2},
\]
i.e.\ \eqref{eq:star} is \emph{identically} the Cauchy--Schwarz second-moment bound
$|\supp r|\ge(\sum r)^2/(\sum r^2)$, with no loss and no gain.
\end{theoremB}

\begin{theoremC}[Dichotomy]
For nonempty $A\subseteq G$ one has $|A|<|A|^4/\Etil(A,A)$ if and only if $|A|<|A+A|$.
Equivalently: either the covering bound strictly improves on pigeonhole, or $A$ is a coset of a
subgroup. In the exceptional case $A=H$ a subgroup of order $h$, one has $\Etil=h^3$,
$E=|G|h^3-h^4$, and the bound returns exactly $h=|H+H|$.
\end{theoremC}

\begin{theoremD}[Three families]
Let $k=|A|$.
\begin{enumerate}
\item \emph{(Sidon)} If $A$ is Sidon then $\Etil(A,A)=2k^2-k$, so $E=|G|(2k^2-k)-k^4$ and the
bound equals $k^3/(2k-1)\ge k^2/2$, while $|A+A|=k(k+1)/2$; the bound is sharp to within a
factor $1+\frac{1}{2k}$. The parabola $P=\{(x,x^2):x\in\ZZ/p\}\subseteq(\ZZ/p)^2$ is Sidon for
odd $p$, giving $E=p^4-p^3$ and bound $p^3/(2p-1)$.
\item \emph{(Exponent two)} If $x+x=0$ for all $x\in G$ and $A$ is Sidon off the diagonal, then
$\Etil(A,A)=3k^2-2k$, $E=|G|(3k^2-2k)-k^4$, the bound equals $k^3/(3k-2)\ge k^2/3$, and
$|A+A|=1+\binom k2$; the bound is off by a factor tending to exactly $3/2$. The radius-one
Hamming ball $\mathcal B_n=\{0,e_1,\dots,e_n\}\subseteq\FF_2^n$ qualifies, giving
$E=2^n(3n^2+4n+1)-(n+1)^4$ and bound $(n+1)^3/(3n+1)$.
\item \emph{(Intervals)} For $I_k=\{0,\dots,k-1\}\subseteq\ZZ/n$ with $2k\le n$,
$\Etil=k(2k^2+1)/3$, $E=\frac{nk(2k^2+1)}{3}-k^4$, and the bound equals $3k^3/(2k^2+1)>k$ for
every $k\ge2$; the exact sumset is $|I_k+I_k|=2k-1$ and the ratio (bound)/(truth) lies in
$[3/4,1)$.
\end{enumerate}
\end{theoremD}

Part (3) deserves emphasis: intervals realise minimal doubling, so no power improvement over
pigeonhole is possible in principle; nevertheless the bound wins by a constant factor
approaching $3/2$, and never overshoots.

\section{Notation}
$G$ is a finite abelian group, $|G|=N$, and $A,B\subseteq G$ are nonempty unless stated
otherwise. $\widehat G$ is the dual group, with trivial character $0$ and
$|\widehat G|=|G|$. For $f,g:G\to\CC$,
\[
\widehat f(\psi)=\sum_{x\in G}f(x)\overline{\psi(x)},\qquad
(f*g)(c)=\sum_{a\in G}f(a)g(c-a),
\]
so that $\widehat{f*g}=\widehat f\,\widehat g$ and Parseval's identity reads
\begin{equation}\label{eq:parseval}
\sum_{x\in G}|f(x)|^2=\frac{1}{|G|}\sum_{\psi\in\widehat G}|\widehat f(\psi)|^2 .
\end{equation}
The covering bound is denoted
\begin{equation}\label{eq:FB}
\FB(A,B)=\frac{|G|(|A||B|)^2}{(|A||B|)^2+E(A,B)} ,
\end{equation}
and the doubling constant of $A$ is $\sigma(A)=|A+A|/|A|\ge1$.

\section{The support, and additive energy as a quadruple count}

\begin{proposition}[Support]\label{prop:supp}
For every $c\in G$, $r_{A,B}(c)>0$ iff $c\in A+B$. Hence $\supp r_{A,B}=A+B$ and
\[
\sum_{c\in A+B}r_{A,B}(c)=|A||B|,\qquad \sum_{c\in A+B}r_{A,B}(c)^2=\Etil(A,B).
\]
\end{proposition}

\begin{proof}
If $r_{A,B}(c)>0$ there is $a\in A$ with $c-a\in B$, so $c=a+(c-a)\in A+B$. Conversely if
$c=a+b$ with $a\in A,b\in B$ then $c-a=b\in B$, so $a$ is counted. Both displays follow since
$r_{A,B}$ and $r_{A,B}^2$ vanish off $A+B$, while every pair $(a,b)$ is counted for exactly one
$c$.
\end{proof}

\begin{proposition}[Fibrewise form]\label{prop:fibre}
$\Etil(A,B)=\sum_{(a,b)\in A\times B} r_{A,B}(a+b)$, and this equals the number of additive
quadruples $(a,b,a',b')\in A\times B\times A\times B$ with $a+b=a'+b'$.
\end{proposition}

\begin{proof}
Partition $A\times B$ into fibres $F_c=\{(a,b):a+b=c\}$; the map $a\mapsto(a,c-a)$ is a
bijection from $\{a\in A: c-a\in B\}$ onto $F_c$, so $|F_c|=r_{A,B}(c)$. Summing the constant
value $r_{A,B}(c)$ over $F_c$ and then over $c$ gives $\sum_c r_{A,B}(c)^2$. The quadruple
description is the same partition read as a count of pairs of pairs with equal sum.
\end{proof}

\begin{proposition}\label{prop:pos}
If $A,B\neq\emptyset$ then $\Etil(A,B)>0$, and $r_{A,B}(c)\le\min(|A|,|B|)$ for all $c$.
\end{proposition}

\begin{proof}
Positivity follows from Proposition~\ref{prop:supp} applied to $c=a_0+b_0$. The pointwise bound
holds because $r_{A,B}(c)$ counts a subset of $A$ (and of $B$).
\end{proof}

\section{Plancherel: the two energies coincide}

\begin{theorem}[Energy identity; Theorem A]\label{thm:energy}
For all $A,B\subseteq G$, $\;E(A,B)=|G|\,\Etil(A,B)-(|A||B|)^2$.
\end{theorem}

\begin{proof}
Apply \eqref{eq:parseval} to $f=r_{A,B}=1_A*1_B$, whose transform is
$\widehat{1_A}\widehat{1_B}$:
\[
\Etil(A,B)=\sum_{c}r_{A,B}(c)^2=\frac1{|G|}\sum_{\psi\in\widehat G}
|\widehat{1_A}(\psi)|^2|\widehat{1_B}(\psi)|^2 .
\]
The trivial character contributes $(|A||B|)^2$; the remaining terms sum to $E(A,B)$ by
definition. Hence $|G|\Etil=(|A||B|)^2+E$.
\end{proof}

\begin{remark}
The identity shows that the (evident) nonnegativity $E\ge0$ is exactly the statement
$\Etil\ge(|A||B|)^2/|G|$, i.e.\ Cauchy--Schwarz for $r_{A,B}$ against the constant function.
\end{remark}

\begin{theorem}[Collapse; Theorem B]\label{thm:collapse}
For nonempty $A,B$, $\;\FB(A,B)=(|A||B|)^2/\Etil(A,B)$.
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:energy} the denominator of \eqref{eq:FB} is
$(|A||B|)^2+\bigl(|G|\Etil-(|A||B|)^2\bigr)=|G|\Etil$, which is positive by
Proposition~\ref{prop:pos}. Cancel $|G|$.
\end{proof}

\begin{theorem}[Covering bound, combinatorial form]\label{thm:cover}
For nonempty $A,B\subseteq G$, $\;(|A||B|)^2/\Etil(A,B)\le|A+B|$.
\end{theorem}

\begin{proof}
Cauchy--Schwarz on $S=A+B=\supp r_{A,B}$ gives
$\bigl(\sum_{c\in S}r_{A,B}(c)\bigr)^2\le|S|\sum_{c\in S}r_{A,B}(c)^2$; apply
Proposition~\ref{prop:supp}.
\end{proof}

\begin{corollary}
For any family whose additive quadruples can be counted, $E$ is available in closed form via
$E=|G|\Etil-(|A||B|)^2$, without evaluating a single character sum.
\end{corollary}

\section{The dichotomy}

Throughout this section $B=A$, $k=|A|$, $\Etil=\Etil(A,A)$.

\begin{lemma}[Criterion]\label{lem:crit}
For nonempty $A,B$: $\max(|A|,|B|)<\FB(A,B)$ iff
$\max(|A|,|B|)\,\Etil(A,B)<(|A||B|)^2$.
\end{lemma}

\begin{proof}
Immediate from Theorem~\ref{thm:collapse} and $\Etil>0$.
\end{proof}

\begin{lemma}[Energy deficit]\label{lem:deficit}
If $A$ is nonempty and $|A|<|A+A|$ then $\Etil(A,A)<|A|^3$.
\end{lemma}

\begin{proof}
Always $r_{A,A}(c)\le k$. If $r_{A,A}(c)=k$ for every $c\in A+A$ then summing over the support
gives $k^2=k|A+A|$, i.e.\ $|A+A|=k$, a contradiction. So some $c_0\in A+A$ has
$r_{A,A}(c_0)<k$, whence
$\Etil=\sum_{c\in A+A}r_{A,A}(c)^2<k\sum_{c\in A+A}r_{A,A}(c)=k^3$.
\end{proof}

\begin{theorem}[Dichotomy; Theorem C]\label{thm:dich}
For nonempty $A\subseteq G$: $\;|A|<\FB(A,A)\iff|A|<|A+A|$.
\end{theorem}

\begin{proof}
($\Leftarrow$) By Lemma~\ref{lem:deficit}, $\FB=k^4/\Etil>k^4/k^3=k$. ($\Rightarrow$) If
$|A+A|\le|A|$ then $\FB\le|A+A|\le|A|$ by Theorem~\ref{thm:cover}.
\end{proof}

\begin{corollary}[Structural form]
For nonempty $A$ and $a\in A$, either $|A|<\FB(A,A)$, or $A=a+H$ with
$H=\{g\in G: g+A=A\}$ the stabiliser of $A$. That is, the bound fails to improve on pigeonhole
only for cosets of subgroups.
\end{corollary}

\begin{proposition}[Subgroups: exact equality]\label{prop:subgroup}
Let $H\le G$ with $h=|H|$. Then $r_{H,H}=h\cdot 1_H$, so $\Etil(H,H)=h^3$,
$E(H,H)=|G|h^3-h^4$, and $\FB(H,H)=h=|H+H|$.
\end{proposition}

\begin{proof}
For $c\in H$ every $y\in H$ has $c-y\in H$, so $r_{H,H}(c)=h$; for $c\notin H$ no such $y$
exists. Hence $\Etil=h^2\cdot h$, and Theorem~\ref{thm:energy} gives $E$; finally
$\FB=(h\cdot h)^2/h^3=h$.
\end{proof}

Thus the bound is exactly tight precisely where it is useless, and strictly informative
everywhere else.

\section{Family I: Sidon sets and the parabola}

\begin{definition}
$A\subseteq G$ is a \emph{Sidon set} if for all $a,b,c,d\in A$, $a+b=c+d$ implies
$\{a,b\}=\{c,d\}$ as unordered pairs.
\end{definition}

\begin{lemma}\label{lem:repsidon}
If $A$ is Sidon with $|A|=k$ then $r_{A,A}(a+a)=1$ for $a\in A$ and $r_{A,A}(a+b)=2$ for
$a\neq b$ in $A$.
\end{lemma}

\begin{proof}
If $y\in A$ and $2a-y\in A$ then $y+(2a-y)=a+a$, so $y=a$ by the Sidon property. If $a\neq b$,
$y\in A$ and $a+b-y\in A$ then $y\in\{a,b\}$, and both occur; the fibre is $\{a,b\}$.
\end{proof}

\begin{theorem}\label{thm:sidon}
Let $A$ be Sidon with $|A|=k\ge1$. Then
\[
\Etil(A,A)=2k^2-k,\qquad E(A,A)=|G|(2k^2-k)-k^4,\qquad \FB(A,A)=\frac{k^3}{2k-1}\ge\frac{k^2}{2},
\]
and $\FB(A,A)>k$ whenever $k\ge2$.
\end{theorem}

\begin{proof}
By Proposition~\ref{prop:fibre} and Lemma~\ref{lem:repsidon}, the diagonal of $A\times A$
contributes $k\cdot1$ and the $k^2-k$ ordered off-diagonal pairs contribute $2$ each, so
$\Etil=k+2(k^2-k)=2k^2-k$. Theorems~\ref{thm:energy} and \ref{thm:collapse} give $E$ and
$\FB=k^4/(2k^2-k)=k^3/(2k-1)\ge k^2/2$. Finally $k^3>k(2k-1)\iff(k-1)^2>0$.
\end{proof}

\begin{theorem}[Exact sumset and sharpness]\label{thm:sidonsharp}
If $A$ is Sidon with $|A|=k$ then $|A+A|=k(k+1)/2$ and
$|A+A|\le\bigl(1+\tfrac1{2k}\bigr)\FB(A,A)$.
\end{theorem}

\begin{proof}
On its support $r_{A,A}\in\{1,2\}$, hence $r^2+2=3r$ there; summing over $A+A$ gives
$\Etil+2|A+A|=3k^2$, so $2|A+A|=k^2+k$. For the second claim,
$\bigl(1+\frac1{2k}\bigr)\frac{k^3}{2k-1}=\frac{k^2(2k+1)}{2(2k-1)}\ge\frac{k(k+1)}2$ is
equivalent to $k(2k+1)\ge(k+1)(2k-1)$, i.e.\ $k\ge-1$.
\end{proof}

\begin{definition}
For an odd prime $p$ let $G=(\ZZ/p)^2$ and $P=\{(x,x^2):x\in\ZZ/p\}$.
\end{definition}

\begin{lemma}\label{lem:parabola}
$|P|=p$, and $P$ is Sidon in $G$ when $p\neq2$.
\end{lemma}

\begin{proof}
Injectivity of $x\mapsto(x,x^2)$ is read off the first coordinate. If
$(x,x^2)+(y,y^2)=(u,u^2)+(v,v^2)$ then $x+y=u+v$ and $x^2+y^2=u^2+v^2$, so
$2xy=(x+y)^2-(x^2+y^2)=2uv$ and hence $xy=uv$ since $2$ is invertible. Then
$(x-u)(x-v)=x^2-(u+v)x+uv=x^2-(x+y)x+xy=0$, so $x=u$ (forcing $y=v$) or $x=v$ (forcing $y=u$).
\end{proof}

For $p=2$ the ``parabola'' is a line, i.e.\ a subgroup, and by Proposition~\ref{prop:subgroup}
no gain is possible: the hypothesis $p\neq2$ is necessary.

\begin{theorem}[The parabola]\label{thm:parabolamain}
For every odd prime $p$, in $G=(\ZZ/p)^2$ of order $p^2$,
\[
E(P,P)=p^4-p^3,\qquad \FB(P,P)=\frac{p^3}{2p-1}\ge\frac{p^2}{2},\qquad
|P+P|=\frac{p(p+1)}{2},
\]
so $\FB(P,P)>p$ and the bound is sharp to within the factor $1+\frac1{2p}$.
\end{theorem}

\begin{proof}
Combine Lemma~\ref{lem:parabola} with Theorems~\ref{thm:sidon} and~\ref{thm:sidonsharp} at
$k=p$, $|G|=p^2$: indeed $E=p^2(2p^2-p)-p^4=p^4-p^3$.
\end{proof}

\section{Family II: exponent two and the Hamming ball}

In a group of exponent two no set of size $\ge2$ is Sidon, since the diagonal maps to $0$.

\begin{definition}
$A\subseteq G$ is \emph{Sidon off the diagonal} if for all $a,b,c,d\in A$ with $a\neq b$ and
$c\neq d$, $a+b=c+d$ implies $\{a,b\}=\{c,d\}$.
\end{definition}

\begin{lemma}[Triple criterion]\label{lem:triple}
Suppose $x+x=0$ for all $x\in G$ and that $a+b+y\notin A$ for all $a,b,y\in A$ with $a\neq b$,
$y\neq a$, $y\neq b$. Then $A$ is Sidon off the diagonal.
\end{lemma}

\begin{proof}
Let $a\neq b$, $c\neq d$ with $a+b=c+d$. If $c=a$ then $b=d$; if $c=b$ then $a=d$. Otherwise
$a+b+c=c+d+c=d\in A$, contradicting the hypothesis.
\end{proof}

\begin{lemma}\label{lem:rep2}
If $x+x=0$ for all $x$ and $A$ is Sidon off the diagonal with $|A|=k$, then $r_{A,A}(0)=k$ and
$r_{A,A}(a+b)=2$ for $a\neq b$ in $A$, and $r_{A,A}$ vanishes elsewhere.
\end{lemma}

\begin{proof}
Since $-y=y$, every $y\in A$ satisfies $0-y\in A$, so $r_{A,A}(0)=k$. For $a\neq b$, if $y\in A$
and $a+b+y\in A$ then $\{y,a+b+y\}$ is a pair of distinct elements with sum $a+b$ (equality
would force $a+b=0$, i.e.\ $a=b$), so $y\in\{a,b\}$; both occur.
\end{proof}

\begin{theorem}\label{thm:sidon2}
With the hypotheses of Lemma~\ref{lem:rep2} and $k=|A|$:
\[
\Etil(A,A)=3k^2-2k,\quad E(A,A)=|G|(3k^2-2k)-k^4,\quad \FB(A,A)=\frac{k^3}{3k-2}\ge\frac{k^2}{3},
\]
with $\FB(A,A)>k$ for $k\ge3$. Moreover $|A+A|=1+\binom k2$ and
$|A+A|\le\frac32\FB(A,A)$, the factor $\frac32$ being asymptotically attained.
\end{theorem}

\begin{proof}
By Proposition~\ref{prop:fibre} the diagonal contributes $k\cdot k=k^2$ and the $k^2-k$ ordered
off-diagonal pairs contribute $2$ each, so $\Etil=3k^2-2k$; hence $\FB=k^3/(3k-2)$. Strictness:
$k^3>k(3k-2)\iff(k-1)(k-2)>0$. The support is $\{0\}$ together with the $\binom k2$ distinct
off-diagonal sums, giving $|A+A|=1+\binom k2$. Finally
$\frac32\frac{k^3}{3k-2}\ge1+\frac{k(k-1)}2$ reduces to $5k^2-8k+4\ge0$, valid for all $k$ since
the discriminant is negative; asymptotically both sides are $\sim k^2/2$.
\end{proof}

The comparison with Theorem~\ref{thm:sidon} is exact and structural: the sole difference between
odd and even characteristic is that in exponent two the diagonal deposits $k^2$ units of energy
on the single point $0$ rather than $k$ units spread over $k$ points. That rigid $k^2$ degrades
the constant from $1/2$ to $1/3$ and the accuracy from $1+\frac1{2k}$ to $3/2$.

\begin{definition}
In $G=\FF_2^n$ let $\mathcal B_n=\{0,e_1,\dots,e_n\}$ be the Hamming ball of radius one.
\end{definition}

\begin{lemma}
$|\mathcal B_n|=n+1$ and $\mathcal B_n$ is Sidon off the diagonal.
\end{lemma}

\begin{proof}
Cardinality is clear. Apply Lemma~\ref{lem:triple}: for $a\neq b$ and $y\notin\{a,b\}$ in
$\mathcal B_n$, the vector $a+b+y$ has weight $\ge2$ in every case (weight three when
$a,b,y$ are three distinct unit vectors; weight two when one of them is $0$), hence lies outside
the ball.
\end{proof}

\begin{theorem}[The Hamming ball]\label{thm:hamming}
For $G=\FF_2^n$ of order $2^n$,
\[
\Etil=3n^2+4n+1,\quad E=2^n(3n^2+4n+1)-(n+1)^4,\quad \FB=\frac{(n+1)^3}{3n+1}\ge\frac{(n+1)^2}{3},
\]
with $\FB>n+1$ for $n\ge2$, and $|\mathcal B_n+\mathcal B_n|=1+\frac{n(n+1)}2$, within a factor
$3/2$ of the bound.
\end{theorem}

\begin{proof}
Apply Theorem~\ref{thm:sidon2} with $k=n+1$: $\Etil=3(n+1)^2-2(n+1)=3n^2+4n+1$ and $3k-2=3n+1$.
\end{proof}

$\FF_2^n$ is the configuration space of $n$ two-level systems and $\mathcal B_n$ is the set of
operations flipping at most one of them; Theorem~\ref{thm:hamming} certifies that composing two
such operations reaches at least $\sim n^2/3$ configurations, whereas pigeonhole certifies only
$n+1$. The true count $1+\binom{n+1}2$ is the number of patterns of weight at most two.

\section{Family III: intervals, the minimal-doubling regime}

\begin{definition}
For $2k\le n$ let $I_k=\{0,1,\dots,k-1\}\subseteq\ZZ/n$.
\end{definition}

\begin{lemma}[Tent function]\label{lem:tent}
Let $2k\le n$ and identify $c\in\ZZ/n$ with its representative $m\in\{0,\dots,n-1\}$. Then
$r_{I_k,I_k}(c)=\min(k,m+1)-\max(0,m+1-k)$: it equals $m+1$ for $0\le m\le k-1$, equals
$2k-1-m$ for $k\le m\le 2k-2$, and vanishes for $m\ge2k-1$.
\end{lemma}

\begin{proof}
Since $2k\le n$, no wraparound occurs: $a+b\le 2k-2<n$ for $a,b\in\{0,\dots,k-1\}$. The number
of integer solutions of $a+b=m$ with $0\le a,b\le k-1$ is the length of
$[\max(0,m+1-k),\min(k,m+1))$.
\end{proof}

\begin{theorem}\label{thm:interval}
For $2k\le n$ and $k\ge1$,
\[
\Etil(I_k,I_k)=\frac{k(2k^2+1)}{3},\qquad E(I_k,I_k)=\frac{n\,k(2k^2+1)}{3}-k^4,\qquad
\FB(I_k,I_k)=\frac{3k^3}{2k^2+1}.
\]
\end{theorem}

\begin{proof}
By Lemma~\ref{lem:tent},
\[
\Etil=\sum_{j=1}^{k}j^2+\sum_{j=1}^{k-1}j^2=\frac{k(k+1)(2k+1)}{6}+\frac{(k-1)k(2k-1)}{6}
=\frac{k(4k^2+2)}{6}=\frac{k(2k^2+1)}{3},
\]
and Theorems~\ref{thm:energy}, \ref{thm:collapse} give $E$ and
$\FB=k^4/\bigl(k(2k^2+1)/3\bigr)$.
\end{proof}

\begin{theorem}[Exact sumset and two-sided accuracy]\label{thm:intervalsharp}
For $2k\le n$ one has $I_k+I_k=I_{2k-1}$, hence $|I_k+I_k|=2k-1$. Moreover for $k\ge2$
\[
k<\FB(I_k,I_k)<2k-1\le\tfrac43\FB(I_k,I_k),
\]
so $\FB/|I_k+I_k|\in[3/4,1)$; and $\FB(I_k,I_k)\ge\frac{3k}{2}-1$ for all $k\ge1$.
\end{theorem}

\begin{proof}
The set identity is Lemma~\ref{lem:tent}. Beating pigeonhole: $3k^3>k(2k^2+1)\iff k^2>1$. Never
tight: $3k^3<(2k-1)(2k^2+1)\iff 0<(k-1)(k^2-k+1)$. Within $4/3$:
$12k^3\ge3(2k-1)(2k^2+1)\iff 6k^2-6k+3\ge0$. Linear bound:
$6k^3\ge(3k-2)(2k^2+1)\iff4k^2-3k+2\ge0$.
\end{proof}

Intervals are the extremal configuration for minimal doubling, so no power gain is available;
nevertheless the second moment detects a constant-factor improvement, converging to
$\frac32 k$ against the truth $2k-1$: a systematic deficit of exactly $25\%$ in the limit,
never more and never zero.

